/**
 * What a run of bot upgrades costs, asked for by name. The sums in `data.ts` take a stat row from
 * the catalog; a caller holding only "Golden Bot" and "Cooldown" has no way to supply one.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    botStatCostBetween
 * depends    src/data/bots/data
 * used by    src/calculators/run-costs, src/data/bots/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { findBotByName, getBotStatMaxLevel, getBotStatMinLevel, normalizeBotStats, sumBotStatCostsBetween } from './data'

/** Letters and digits only, so `Cooldown`, `cooldown` and `cool-down` all match. */
const statKey = (value: string): string => value.toLowerCase().replace(/[^a-z0-9]+/g, '')

/**
 * Medals to take one of a bot's stats from `fromLevel` to `toLevel`.
 *
 * Sums the levels bought, `fromLevel + 1` through `toLevel`; a level's cost is what it takes to
 * reach it, and level 0 is the bot as unlocked. `0` when the two are equal. `null` for an unknown
 * bot or stat, a level that is not a whole number, `toLevel` below `fromLevel`, or a level outside
 * the stat's ladder — the underlying sum clamps a level past the cap, which reads as a real total.
 */
export function botStatCostBetween(
  botLabel: string,
  statName: string,
  fromLevel: number,
  toLevel: number,
): number | null {
  const bot = findBotByName(String(botLabel ?? ''))
  if (!bot) return null

  const wanted = statKey(String(statName ?? ''))
  const stat = normalizeBotStats(bot).find(row => statKey(row.name) === wanted)
  if (!stat || !wanted) return null

  if (!Number.isInteger(fromLevel) || !Number.isInteger(toLevel)) return null
  if (fromLevel < getBotStatMinLevel(stat) || toLevel < fromLevel || toLevel > getBotStatMaxLevel(stat)) return null

  return sumBotStatCostsBetween(stat, fromLevel, toLevel)
}
